// Integer actor of the Meowmind RL export: the repository's INT16 format (reference16, training/meow_rl/quant.py).
// Include a header generated by training.meow_rl.quant.header (namespace meow_rl_model, a fusion::Net) first and
// build with -I inference. The network runs on inference/mlp.hpp's fusion::forwardRaw; results equal
// fusion.quant.forward_raw bit for bit on every platform and SIMD path.
#pragma once
#include <algorithm>
#include <cmath>
#include <cstdint>

#include "mlp.hpp"

namespace meow_rl_int {

static_assert(meow_rl_model::kInBits == 12, "inputs are features * 2^12");
constexpr int32_t kInMax = 4 << meow_rl_model::kInBits;   // features are clamped to [-4, 4]

inline int32_t quantize_input(float x) {
    // x * 2^12 is exact in double; floor(v + 1/2) is the repository's rounding (quant.quantize_input).
    double v = std::floor(double(x) * double(1 << meow_rl_model::kInBits) + 0.5);
    return int32_t(std::clamp(v, double(-kInMax), double(kInMax)));
}

// Output accumulator of one unit-move feature vector (logit = acc / 2^outExp).
inline int32_t score(const float* feats) {
    int32_t x[112], acc[1];
    for (int i = 0; i < 112; i++) x[i] = quantize_input(feats[i]);
    fusion::forwardRaw(meow_rl_model::kActor, x, acc);
    return acc[0];
}

// Greedy joint move j = 25 a + 5 b + c over the feasible mask; ties go to the lowest index (quant.greedy).
inline int greedy(const float (*feats)[5][112], const unsigned char* mask) {
    int64_t s[3][5];
    for (int k = 0; k < 3; k++)
        for (int m = 0; m < 5; m++) s[k][m] = score(feats[k][m]);
    int best = -1;
    int64_t top = 0;
    for (int j = 0; j < 125; j++) {
        if (!mask[j]) continue;
        int64_t z = s[0][j / 25] + s[1][j / 5 % 5] + s[2][j % 5];
        if (best < 0 || z > top) best = j, top = z;
    }
    return best;
}

}  // namespace meow_rl_int
